\[
\mathcal P_{d,\epsilon,M,\sigma}
:=
\left\{
P:
\begin{array}{l}
X\in\{1,\ldots,d\},\ A\in\{0,1\},\ Y,Y(0),Y(1)\in\mathbb R,\\
0<\epsilon<1/2,\quad M\ge 1,\quad 0\le \sigma\le 2,\\
P\text{ satisfies }\cref{obj:ass:consistency,obj:ass:conditional-exchangeability,obj:ass:overlap,obj:ass:mean-normalization,obj:ass:second-central-moment,obj:ass:approximate-homogeneity}
\end{array}
\right\}.
\]

\[
\mathcal P_{d,\epsilon,M}^{\mathrm{unr}}
:=
\left\{
P:
\begin{array}{l}
X\in\{1,\ldots,d\},\ A\in\{0,1\},\ Y,Y(0),Y(1)\in\mathbb R,\\
0<\epsilon<1/2,\quad M\ge 1,\\
P\text{ satisfies }\cref{obj:ass:consistency,obj:ass:conditional-exchangeability,obj:ass:overlap,obj:ass:mean-normalization,obj:ass:second-central-moment}
\end{array}
\right\}.
\]

Let
\[
\mathcal T_{n,M}
:=
\bigl\{
T:\mathcal O^n\to[-M,M]\;:\;T\ \text{is measurable}
\bigr\}.
\]
The minimax mean-squared risk over \(\mathcal P_{d,\epsilon,M,\sigma}\) is
\[
\mathsf R_{n,d,\epsilon,M,\sigma}
:=
\inf_{T\in\mathcal T_{n,M}}
\sup_{P\in\mathcal P_{d,\epsilon,M,\sigma}}
E_{Q_P^{(n)}}\!\left[(T-\tau(P))^2\right].
\]

For every overlap parameter \(\epsilon\) satisfying \(0<\epsilon<1/2\), there exists a constant \(c_{\epsilon}>0\) such that the following holds. For every \(n,d\in\mathbb N\) and every \(M,\sigma\in\mathbb R\), suppose that
\begin{itemize}
\item \textbf{(Sample and alphabet sizes.)} \(n\ge 1\) and \(d\ge 1\);
\item \textbf{(Outcome radius.)} \(M\ge 1\);
\item \textbf{(Noise radius.)} \(0\le \sigma\le 2\).
\end{itemize}
Then the minimax mean-squared risk \(\mathsf R_{n,d,\epsilon,M,\sigma}\) of \cref{obj:def:minimax-risk} satisfies
\[
\mathsf R_{n,d,\epsilon,M,\sigma}\ge \frac{c_{\epsilon}M^2}{n}.
\]

For every overlap parameter \(0<\epsilon<1/2\), there is a constant \(C_{\epsilon}>0\) such that the following statement holds.  Let \(d,m\), and \(K\) be nonnegative integers, let \(M,\sigma,B\in\mathbb R\), let \(P\in\mathcal P_{d,\epsilon,M,\sigma}\) as in \cref{obj:def:model-class}, and let \(S\subseteq\{1,\ldots,d\}\) be deterministic.  For a block of \(m\) independent observations with joint law \(Q_P^{(m)}\), write \(V_i=Y_i/M\).  For the polynomial degree \(K\), define the shifted-Chebyshev coefficients
\[
g_{Kj}
:=
(-1)^j\frac{2^{2j+3}}{K(K+j+2)}
\binom{K+j+2}{2j+4},
\qquad 0\le j\le K-2.
\]
For \(0\le j\le K-2\), define
\[
U_{k,a,j}
:=
\frac{1}{(m)_{j+2}}
\sum_{i_0,\ldots,i_{j+1}\ {\rm distinct}}
V_{i_0}\mathbf 1\{X_{i_0}=k,A_{i_0}=a\}
\mathbf 1\{X_{i_1}=k\}
\prod_{t=2}^{j+1}\mathbf 1\{X_{i_t}=k,A_{i_t}=a\}.
\]
Set
\[
\widehat P_k
:=
\sum_{j=0}^{K-2}
\frac{g_{Kj}}{B^{j+1}}
\{U_{k,1,j}-U_{k,0,j}\}.
\]
Assume that
\begin{itemize}
\item \textbf{(Degree.)} \(K\ge 2\).
\item \textbf{(Scale.)} \(B>0\).
\item \textbf{(Light cells.)} \(p_k\le B/4\) for every \(k\in S\).
\item \textbf{(Block size.)} \(4(K+2)^2\le m\).
\item \textbf{(Shift calibration.)} \(4(K+2)/m\le 3B/4\).
\end{itemize}
Then
\[
\operatorname{Var}_{Q_P^{(m)}}\!\left(\sum_{k\in S}\widehat P_k\right)
\le
\frac{C_{\epsilon}}{m}
+
C_{\epsilon}6^{2K}
\left\{
dB^2+\frac{d^2K^2B^2}{m}
\right\}.
\]

For every overlap parameter \(\epsilon\) with \(0<\epsilon<1/2\), there exist real constants \(c_{\epsilon}\) and \(C_{\epsilon}\) such that
\[
0<c_{\epsilon}\le 1,\qquad 1\le C_{\epsilon},\qquad c_{\epsilon}\le C_{\epsilon}.
\]
For every pair of positive integers \(n,d\) and every \(M,\sigma\in\mathbb R\), assume:
\begin{itemize}
\item \textbf{(Scale.)} \(1\le M\).
\item \textbf{(Radius.)} \(0\le \sigma\le 2\).
\item \textbf{(Range.)}
\[
d\le \frac{c_{\epsilon}n^2}{\log(en)}.
\]
\end{itemize}
Let \(\mathsf R_{n,d,\epsilon,M,\sigma}\) be the minimax mean-squared risk in \cref{obj:def:minimax-risk}. Then
\[
c_{\epsilon}M^2\left\{
\frac{1}{n}+\frac{d}{n^2}
+\sigma^2\min\left(1,\frac{d^2}{n^2\log^2(en)}\right)
\right\}
\le
\mathsf R_{n,d,\epsilon,M,\sigma}
\le
C_{\epsilon}M^2\left\{
\frac{1}{n}
+\min\left(1,\min\left(\frac{d^2}{n^2\log^2(en)},\,\sigma^2+\frac{d}{n^2}\right)\right)
\right\}.
\]

For every overlap parameter \(\epsilon\) with \(0<\epsilon<1/2\), there exists a constant \(c_{\epsilon}>0\) such that the following statement holds.  For every \(n,d\in\mathbb N\), \(M\in\mathbb R\), and \(\sigma\in\mathbb R\) satisfying
\begin{itemize}
\item \textbf{(Sample and alphabet.)} \(n\ge 1\) and \(d\ge 1\);
\item \textbf{(Outcome scale.)} \(M\ge 1\);
\item \textbf{(Radius range.)} \(0\le \sigma\le 2\),
\end{itemize}
the minimax mean-squared risk \(\mathsf R_{n,d,\epsilon,M,\sigma}\) from \cref{obj:def:minimax-risk} obeys
\[
c_{\epsilon}M^2\left\{\frac{1}{n}+\min\left(1,\frac{d}{n^2}\right)\right\}
\le
\mathsf R_{n,d,\epsilon,M,\sigma}.
\]

Let \(u_{\epsilon}:=\min\{1/2,\,8(1/2-\epsilon)^2\}\).  Suppose that:
\begin{itemize}
\item \textbf{(Sample and alphabet.)} \(n,d\in\mathbb N\) satisfy \(n\ge 1\) and \(d\ge 1\).
\item \textbf{(Overlap.)} The overlap parameter \(\epsilon\in\mathbb R\) satisfies \(0<\epsilon<1/2\).
\item \textbf{(Collision regime.)} The dimensions satisfy \(d\le n^2\).
\end{itemize}
For the fixed-sample binary exactly homogeneous source experiment \(\mathcal H_{n,d}^{\mathrm{bin}}(\epsilon)\), generated by binary laws with uniform cell masses, propensities in \([\epsilon,1-\epsilon]\), and a common cell effect across all cells, the minimax mean-squared risk for estimating the binary average response contrast \(\psi(P)\) satisfies
\[
\frac{u_{\epsilon}^2}{64}\frac{d}{n^2}
\le
\inf_{\widehat\psi}
\sup_{P\in\mathcal H_{n,d}^{\mathrm{bin}}(\epsilon)}
E_{P^{\otimes n}}\!\left[\{\widehat\psi-\psi(P)\}^2\right],
\]
where the infimum ranges over all measurable real-valued estimators \(\widehat\psi\) of the \(n\)-sample.

